#include <stdlib.h>
#include <stdio.h>

int main(void) {
    // malloc's 5 integers
    int* x = (int*) malloc(5 * sizeof(int));

    if(x == NULL) {
        perror("Error allocating array x"); // perror is like printf but also prints the error message
    }

    x[0] = 6;
    x[1] = 7;

    printf("%d\n", x[0]);

    free(x);
}
